"""Bounded Bilibili video downloads using progressive audio/video streams."""

import asyncio
import re
from pathlib import Path
from urllib.parse import urljoin, urlsplit

import aiohttp


class VideoDownloadError(Exception):
    """The video cannot be downloaded or prepared for forwarding."""


class VideoTooLargeError(VideoDownloadError):
    """The video exceeds the configured forwarding size limit."""


def video_request(api_url: str, page_match=None) -> tuple[dict, int] | None:
    """Accept ordinary video metadata URLs generated by the parser.

    Args:
        api_url: Metadata URL produced by the existing parser.
        page_match: Optional parser regex match for the selected part.

    Returns:
        Video identifiers and part number, or None for other content.

    Raises:
        VideoDownloadError: The selected part number is invalid.
    """
    from urllib.parse import parse_qs

    parsed = urlsplit(api_url)
    if parsed.hostname != "api.bilibili.com" or parsed.path != "/x/web-interface/view":
        return None
    query = parse_qs(parsed.query)
    params = {}
    for key, pattern in (("bvid", r"BV[A-Za-z0-9]{10}"), ("aid", r"[0-9]+")):
        value = query.get(key, [""])[0]
        if re.fullmatch(pattern, value, re.IGNORECASE):
            params[key] = value
            break
    if not params:
        return None
    page = 1
    if page_match:
        match = re.search(r"p=(\d+)", page_match[0])
        if match:
            page = int(match[1])
    if page < 1:
        raise VideoDownloadError("Invalid video page")
    return params, page


def allowed_media_url(url: str) -> bool:
    parsed = urlsplit(url)
    host = (parsed.hostname or "").lower().rstrip(".")
    domains = ("bilivideo.com", "bilivideo.cn", "bilivideo.net", "akamaized.net")
    return (
        parsed.scheme in ("https", "http")
        and not parsed.username
        and not parsed.password
        and parsed.port in (None, 80, 443)
        and any(host == d or host.endswith("." + d) for d in domains)
    )


async def _api(session: aiohttp.ClientSession, url: str, params: dict) -> dict:
    async with session.get(
        url, params=params, timeout=aiohttp.ClientTimeout(total=20)
    ) as response:
        response.raise_for_status()
        result = await response.json()
    if result.get("code") != 0 or not isinstance(result.get("data"), dict):
        raise VideoDownloadError(f"Bilibili API code {result.get('code')}")
    return result["data"]


async def _download(
    session: aiohttp.ClientSession, url: str, target: Path, max_bytes: int
) -> None:
    for _ in range(6):
        if not allowed_media_url(url):
            raise VideoDownloadError("Untrusted media URL")
        async with session.get(
            url,
            headers={"Range": "bytes=0-"},
            timeout=aiohttp.ClientTimeout(total=180, sock_read=30),
            allow_redirects=False,
        ) as response:
            if response.status in (301, 302, 303, 307, 308):
                location = response.headers.get("Location")
                if not location:
                    raise VideoDownloadError("Missing redirect location")
                url = urljoin(url, location)
                continue
            if response.status not in (200, 206):
                raise VideoDownloadError(f"Media HTTP {response.status}")
            expected = response.content_length
            if response.status == 206:
                content_range = re.fullmatch(
                    r"bytes 0-(\d+)/(\d+)", response.headers.get("Content-Range", "")
                )
                if not content_range or int(content_range[1]) + 1 != int(
                    content_range[2]
                ):
                    raise VideoDownloadError("Incomplete media range")
                expected = int(content_range[2])
            if expected is not None and expected > max_bytes:
                raise VideoTooLargeError("Video exceeds size limit")
            size = 0
            with target.open("wb") as output:
                async for chunk in response.content.iter_chunked(256 * 1024):
                    size += len(chunk)
                    if size > max_bytes:
                        raise VideoTooLargeError("Video exceeds size limit")
                    output.write(chunk)
            if not size or (expected is not None and size != expected):
                raise VideoDownloadError("Incomplete media download")
            return
    raise VideoDownloadError("Too many media redirects")


async def _remux(source: Path, target: Path) -> None:
    process = await asyncio.create_subprocess_exec(
        "ffmpeg",
        "-nostdin",
        "-hide_banner",
        "-loglevel",
        "error",
        "-y",
        "-protocol_whitelist",
        "file,pipe",
        "-i",
        str(source),
        "-map",
        "0:v:0",
        "-map",
        "0:a:0",
        "-c",
        "copy",
        "-movflags",
        "+faststart",
        str(target),
        stdout=asyncio.subprocess.DEVNULL,
        stderr=asyncio.subprocess.DEVNULL,
    )
    try:
        code = await asyncio.wait_for(process.wait(), timeout=45)
    finally:
        if process.returncode is None:
            process.kill()
            await process.wait()
    if code or not target.exists() or not target.stat().st_size:
        raise VideoDownloadError("Cannot prepare MP4 audio/video")


async def download_video(
    session: aiohttp.ClientSession,
    request: tuple[dict, int],
    directory: Path,
    max_bytes: int,
) -> Path:
    """Download the selected part, retaining its original soundtrack.

    Args:
        session: Shared HTTP session with Bilibili headers.
        request: Video identifiers and selected part number.
        directory: Isolated temporary download directory.
        max_bytes: Maximum permitted video size in bytes.

    Returns:
        Local MP4 path containing both video and audio.

    Raises:
        VideoDownloadError: No complete, usable video is available.
    """
    params, page = request
    metadata = await _api(
        session, "https://api.bilibili.com/x/web-interface/view", params
    )
    pages = metadata.get("pages") or []
    if not 1 <= page <= len(pages):
        raise VideoDownloadError("Video page unavailable")
    play_params = {
        **params,
        "cid": pages[page - 1]["cid"],
        "qn": 64,
        "fnval": 1,
        "platform": "html5",
    }
    play = await _api(session, "https://api.bilibili.com/x/player/playurl", play_params)
    streams = play.get("durl") or []
    if len(streams) != 1:
        raise VideoDownloadError("Progressive video unavailable")
    stream = streams[0]
    if int(stream.get("size") or 0) > max_bytes:
        raise VideoTooLargeError("Video exceeds size limit")
    source = directory / "source.bin"
    target = directory / "video.mp4"
    urls = [stream.get("url"), *(stream.get("backup_url") or [])]
    for url in dict.fromkeys(url for url in urls if isinstance(url, str)):
        try:
            await _download(session, url, source, max_bytes)
            break
        except VideoTooLargeError:
            source.unlink(missing_ok=True)
            raise
        except (aiohttp.ClientError, asyncio.TimeoutError, VideoDownloadError):
            source.unlink(missing_ok=True)
    else:
        raise VideoDownloadError("All video download sources failed")
    await _remux(source, target)
    source.unlink(missing_ok=True)
    if target.stat().st_size > max_bytes:
        raise VideoTooLargeError("Prepared video exceeds size limit")
    return target
